package example.bankwealth.infrastructure.projection

import scalapb.GeneratedMessage
import BankJournalReadsideRepository.{Row, State}

object BankJournalReadsideDomain {
  def accountState(row: Row): example.bankwealth.domain.CreditBalanceState = {
    require(row.kind == "account", "stream kind mismatch")
    row.payload.map(bytes => example.bankwealth.infrastructure.serialization.DomainConverters.decodeCreditBalanceStatePO(example.bankwealth.infrastructure.proto.CreditBalanceStatePO.parseFrom(bytes)))
      .getOrElse(example.bankwealth.domain.CreditBalanceState.empty.copy(id = example.bankwealth.domain.values.AccountId(row.resource)))
  }
  def orderState(row: Row): example.bankwealth.domain.FundOrderState = {
    require(row.kind == "order", "stream kind mismatch")
    row.payload.map(bytes => example.bankwealth.infrastructure.serialization.DomainConverters.decodeFundOrderStatePO(example.bankwealth.infrastructure.proto.FundOrderStatePO.parseFrom(bytes)))
      .getOrElse(example.bankwealth.domain.FundOrderState.empty.copy(id = example.bankwealth.domain.values.FundOrderId(row.resource)))
  }
  def planState(row: Row): example.bankwealth.domain.SipPlanState = {
    require(row.kind == "plan", "stream kind mismatch")
    row.payload.map(bytes => example.bankwealth.infrastructure.serialization.DomainConverters.decodeSipPlanStatePO(example.bankwealth.infrastructure.proto.SipPlanStatePO.parseFrom(bytes)))
      .getOrElse(example.bankwealth.domain.SipPlanState.empty.copy(id = example.bankwealth.domain.values.PlanId(row.resource)))
  }
  trait Ownership {
    def account(row: Row, next: example.bankwealth.domain.CreditBalanceState): (Option[String], Option[String])
    def order(row: Row, next: example.bankwealth.domain.FundOrderState): (Option[String], Option[String])
    def plan(row: Row, next: example.bankwealth.domain.SipPlanState): (Option[String], Option[String])
  }
  def fold(row: Row, event: Any, ownership: Ownership): State = row.kind match {
    case "account" =>
      val message = event match {
        case pb: GeneratedMessage => pb
        case _ => throw new IllegalArgumentException("domain journal must contain protobuf")
      }
      val next = example.bankwealth.infrastructure.serialization.CreditBalanceEventAdapter
        .fromJournal(message, message.getClass.getSimpleName).events.foldLeft(accountState(row)) { (state, event) =>
          event match {
            case value: example.bankwealth.domain.CreditBalanceProtocol.AccountInitialized =>
              require(value.resource.value == row.resource, "account event identity mismatch")
            case value: example.bankwealth.domain.CreditBalanceProtocol.ReserveFundsConfirmed =>
              require(value.resource.value == row.resource, "account event identity mismatch")
            case value: example.bankwealth.domain.CreditBalanceProtocol.DeductFundsConfirmed =>
              require(value.resource.value == row.resource, "account event identity mismatch")
            case value: example.bankwealth.domain.CreditBalanceProtocol.ReleaseReservedFundsConfirmed =>
              require(value.resource.value == row.resource, "account event identity mismatch")
            case value: example.bankwealth.domain.CreditBalanceProtocol.RecordIncomingCreditsConfirmed =>
              require(value.resource.value == row.resource, "account event identity mismatch")
            case value: example.bankwealth.domain.CreditBalanceProtocol.CommitIncomingCreditsConfirmed =>
              require(value.resource.value == row.resource, "account event identity mismatch")
            case value: example.bankwealth.domain.CreditBalanceProtocol.CancelIncomingCreditConfirmed =>
              require(value.resource.value == row.resource, "account event identity mismatch")
            case _ => ()
          }
          example.bankwealth.domain.CreditBalanceEventHandler(state, event)
        }
      require(next.id.value == row.resource, "account identity mismatch")
      val (account, principal) = ownership.account(row, next)
      State(Some(example.bankwealth.infrastructure.serialization.DomainConverters.encodeCreditBalanceStatePO(next).toByteArray), account, principal)
    case "order" =>
      val message = event match {
        case pb: GeneratedMessage => pb
        case _ => throw new IllegalArgumentException("domain journal must contain protobuf")
      }
      val next = example.bankwealth.infrastructure.serialization.FundOrderEventAdapter
        .fromJournal(message, message.getClass.getSimpleName).events.foldLeft(orderState(row)) { (state, event) =>
          example.bankwealth.domain.FundOrderEventHandler(state, event)
        }
      require(next.id.value == row.resource, "order identity mismatch")
      val (account, principal) = ownership.order(row, next)
      State(Some(example.bankwealth.infrastructure.serialization.DomainConverters.encodeFundOrderStatePO(next).toByteArray), account, principal)
    case "plan" =>
      val message = event match {
        case pb: GeneratedMessage => pb
        case _ => throw new IllegalArgumentException("domain journal must contain protobuf")
      }
      val next = example.bankwealth.infrastructure.serialization.SipPlanEventAdapter
        .fromJournal(message, message.getClass.getSimpleName).events.foldLeft(planState(row)) { (state, event) =>
          example.bankwealth.domain.SipPlanEventHandler(state, event)
        }
      require(next.id.value.isEmpty || next.id.value == row.resource, "plan identity mismatch")
      val (account, principal) = ownership.plan(row, next)
      State(Some(example.bankwealth.infrastructure.serialization.DomainConverters.encodeSipPlanStatePO(next).toByteArray), account, principal)
    case "payment-saga" | "payment-host" | "payment-run" | "refund-saga" | "refund-host" | "refund-run" | "ta-host" | "ta-run" | "sip-host" | "sip-run" => State(None, None, None)
    case _ => throw new IllegalArgumentException("unrecognized persistence kind")
  }
}

